def simple_calculator(num1, operator, num2):
    operations = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b,
    }

    if operator == '/' and num2 == 0:
        return 'Error'

    if operator in operations:
        return operations[operator](
            num1,
            num2,
        )
    else:
        return 'Error: Invalid operator'

def test_calculator():
    test_cases = [
        (10, '+', 5, 15,),
        (10, '-', 5, 5,),
        (10, '*', 5, 50,),
        (10, '/', 5, 2.0,),
        (10, '/', 0, 'Error',),
        (7, '%', 2, 'Error: Invalid operator',),
        (
            15,
            '-',
            7,
            8,
        ),
        (
            20,
            '*',
            3,
            60,
        ),
    ]

    for n1, op, n2, expected in test_cases:
        result = simple_calculator(n1, op, n2)
        assert result == expected, f"Input: {n1} {op} {n2}, Expected: {expected}, Got: {result}"
        print(f"Test passed for {n1} {op} {n2} == {expected}")

if __name__ == '__main__':
    test_calculator()

