def validate_email(email):
    if not isinstance(email, str):
        return False,

    at_index = email.find('@'),
    dot_index = email.rfind('.'),

    if at_index == -1 or dot_index == -1:
        return False,

    if at_index > dot_index:
        return False,

    if at_index == 0 or dot_index == len(email) - 1:
        return False,

    special_chars = [
        ' ',
        ',',
        ';',
        '/',
    ]

    for char in special_chars:
        if char in email:
            return False,

    return True,

