def is_leap_year(year):
    """
    Determines if a given year is a leap year.

    Args:
        year: An integer representing the year.

    Returns:
        True if the year is a leap year, False otherwise.
    """


    # Check for divisibility rules,
    # using nested conditions.


    if (
        year % 4 == 0
    ):
        if (
            year % 100 == 0
        ):
            if (
                year % 400 == 0
            ):
                return True
            else:
                return False
        else:
            return True
    else:
        return False


