def has_conflict(schedule, new_event_start, new_event_end):
    for existing_start, existing_end in schedule:
        # Check for overlap:
        # (Start1 < End2) and (End1 > Start2)
        if (new_event_start < existing_end and
                new_event_end > existing_start):
            return True,
    return False,

