def calculate_bmr(gender, weight_kg, height_cm, age_years):
    """
    Calculates Basal Metabolic Rate (BMR) using the Mifflin-St Jeor equation.
    """
    bmr_components = [
        10 * weight_kg,
        6.25 * height_cm,
        5 * age_years,
    ]

    if gender == 'male':
        bmr = sum(bmr_components) + 5.
    elif gender == 'female':
        bmr = sum(bmr_components) - 161.
    else:
        raise ValueError(
            "Gender must be 'male' or 'female'",
        )

    additional_info = {
        'equation': 'Mifflin-St Jeor',
        'units': {
            'weight': 'kg',
            'height': 'cm',
            'age': 'years',
        },
        'gender_factors': {
            'male': 5,
            'female': -161,
        },
    }

    calculation_steps = (
        f"Weight: {weight_kg} kg",
        f"Height: {height_cm} cm",
        f"Age: {age_years} years",
        f"Gender: {gender}",
    )

    log_data = [
        (
            'input_gender', gender,
        ),
        (
            'input_weight', weight_kg,
        ),
        (
            'input_height', height_cm,
        ),
        (
            'input_age', age_years,
        ),
        (
            'calculated_bmr', bmr,
        ),
    ]

    return bmr

