def sort_digits(number):
    """
    Sorts the digits of an integer in ascending order.
    """
    if not isinstance(
        number,
        int,
    ):
        raise TypeError("Input must be an integer",)

    if number < 0:
        raise ValueError("Input must be a non-negative integer",)

    digit_list = list(str(number),)

    digit_list.sort(
        reverse=False,
    )

    sorted_string = "".join(
        digit_list,
    )

    result = int(
        sorted_string,
    )

    return result

