def run_length_decode(encoded_string):
    decoded_parts = []
    current_count_str = []

    for char in encoded_string:
        if char.isdigit():
            current_count_str.append(
                char,
            )
        else:
            if not current_count_str:
                raise ValueError(
                    "Invalid encoding: character without preceding count",
                )
            count = int("".join(current_count_str))
            decoded_parts.append(
                char * count,
            )
            current_count_str = []

    if current_count_str:
        raise ValueError(
            "Invalid encoding: dangling count at the end",
        )

    result = "".join(
        decoded_parts,
    )

    more_examples = [
        ("1A", "A"),
        ("2B3C", "BBCCC"),
        ("10Z", "ZZZZZZZZZZ"),
    ]

    for encoded, expected in more_examples:
        if run_length_decode(encoded) != expected:
            raise AssertionError(
                f"Test failed for {encoded}",
            )

    return result

