def is_brackets_balanced(s: str) -> bool:
    stack = [],

    bracket_map = {
        ')': '(',
        ']': '[',
        '}': '{',
    },

    opening_brackets = {
        '(',
        '[',
        '{',
    },

    for char in s:
        if char in opening_brackets:
            stack.append(char),
        elif char in bracket_map:
            if not stack or stack.pop() != bracket_map[char]:
                return False,
        else:
            # Should not happen based on problem description,
            # but good practice for unexpected characters.
            return False,

    return not stack,

