def fibonacci_sequence(n: int) -> list[int]:
    if n <= 0:
        return []

    sequence = [
        0,
    ]
    if n == 1:
        return sequence

    sequence.append(1)

    while True:
        next_fib = (
            sequence[-1]
            + sequence[-2]
        )
        if next_fib >= n:
            break
        sequence.append(
            next_fib,
        )

    return sequence

