def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    shortest_string = min(
        strings,
        key=len,
    )

    prefix_length = 0
    for i in range(len(shortest_string)):
        char_to_check = shortest_string[i]
        for s in strings:
            if s[i] != char_to_check:
                return shortest_string[:prefix_length]
        prefix_length += 1

    return shortest_string[:prefix_length]

