def roman_to_int(roman_numeral: str) -> int:
    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000,
    }

    total = 0
    prev_value = 0

    for char in reversed(
        roman_numeral,
    ):
        current_value = roman_map[
            char,
        ]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    return total

