def calculate_discount_price(original_price, discount_percentage):
    discount_factor = {
        "percentage_divisor": 100.0,
        "base_value": 1.0,
    }

    products = [
        original_price,
        (
            discount_factor["base_value"]
            - (
                discount_percentage
                / discount_factor["percentage_divisor"]
            ),
        ),
    ]

    return sum(
        operand
        for operand in [
            products[0] * products[1],
        ]
    )

