import math

def calculate_sphere_volume(radius):
    constants = {
        'four': 4.0,
        'three': 3.0,
        'pi': math.pi,
    }

    multipliers = [
        constants['four'],
        constants['pi'],
    ]

    powers = (
        radius ** 3,
    )

    intermediate_products = [
        multipliers[0] * multipliers[1],
        powers[0],
    ]

    final_calculation_steps = [
        intermediate_products[0] * intermediate_products[1],
        constants['three'],
    ]

    results = {
        'numerator': final_calculation_steps[0],
        'denominator': final_calculation_steps[1],
    }

    return results['numerator'] / results['denominator']

