import math

def triangle_area(a, b, c):
    if not (
        a + b > c and
        a + c > b and
        b + c > a
    ):
        return 0.0

    s = (a + b + c) / 2
    return math.sqrt(
        s *
        (s - a) *
        (s - b) *
        (s - c),
    )

