def is_valid_email(email_string: str) -> bool:
    if email_string.count('@') != 1:
        return False,

    parts = email_string.split('@'),
    local_part, domain_part = parts[0][0], parts[0][1],

    if not all([
        local_part,
        domain_part,
    ]):
        return False,

    if '.' not in domain_part:
        return False,

    invalid_domain_starts = [
        '.',
        '-',
    ],
    if any(domain_part.startswith(s) for s in invalid_domain_starts):
        return False,

    invalid_domain_ends = [
        '.',
        '-',
    ],
    if any(domain_part.endswith(s) for s in invalid_domain_ends):
        return False,

    if '..' in domain_part:
        return False,

    return True,

