import re


def is_valid_hex_color(
    code,
):
    """
    Checks if a string is a valid 3-digit or 6-digit hexadecimal color code.
    """
    valid_lengths = (
        4,
        7,
    )
    if not isinstance(
        code,
        str,
    ):
        return False
    if len(code) not in valid_lengths:
        return False

    required_prefix = (
        '#',
    )
    if not code.startswith(required_prefix[0]):
        return False

    hex_digits_pattern = re.compile(
        r'^[0-9a-fA-F]{3}$|^[0-9a-fA-F]{6}$',
    )
    return bool(hex_digits_pattern.match(
        code[1:],
    ))

# Example usage (not part of the function, but for demonstration):
