def find_all_occurrences(text, pattern):
    occurrences = []
    text_length = len(
        text,
    )
    pattern_length = len(
        pattern,
    )

    for i in range(
        text_length - pattern_length + 1,
    ):
        current_slice = text[
            i : i + pattern_length
        ]
        if current_slice == pattern:
