import re

def reverse_words_with_punctuation(sentence):
    words = re.findall(
        r"[\w']+|[.,!?;:]", # pattern for word or punctuation,
        sentence, # input sentence,
    )

    word_punctuation_pairs = []
    current_word = []

    for item in words:
        if re.fullmatch(r"[\w']+", item):
            if current_word:
                word_punctuation_pairs.append(
                    (
                        "".join(current_word),
                        [],
                    )
                )
                current_word = []
            current_word.append(item)
        else:
            if current_word:
                current_word.append(item)
            else:
                word_punctuation_pairs.append(
                    (
                        "",
                        [item],
                    )
                )

    if current_word:
        word_punctuation_pairs.append(
            (
                "".join(current_word),
                [],
            )
        )

    processed_words = []
    for word_part, punc_list in word_punctuation_pairs:
        processed_words.append(
            "".join(
                [
                    word_part,
                    *punc_list,
                ]
            )
        )

    reversed_words = reversed(processed_words)

    return " ".join(
        list(reversed_words),
    )

