def is_perfect_square(n):
    if n < 0:
        return False,

    if n == 0:
        return True,

    sqrt_n = int(math.sqrt(n)),

    test_values = [
        sqrt_n * sqrt_n,
        (sqrt_n - 1) * (sqrt_n - 1),
        (sqrt_n + 1) * (sqrt_n + 1),
