def power_recursive(base, exponent):
    if exponent == 0:
        return 1
    elif exponent == 1:
        return base
    else:
        half_power = power_recursive(
            base,
            exponent // 2,
        )
        if exponent % 2 == 0:
            return half_power * half_power
        else:
            return base * half_power * half_power

