        ([], 0.0,),
        ([1, 1, 1, 1, 1,], 0.0,),
    ]

    for numbers_list, expected_std_dev in test_cases:
        actual_std_dev = calculate_sample_std_dev(
            numbers_list,
        )
        assert abs(actual_std_dev - expected_std_dev) < 1e-9, \
            f"For {numbers_list}, expected {expected_std_dev}, got {actual_std_dev}"

